mapper.select:
SELECT id FROM hyperlink_task_round WHERE tenant_id=#{tenantId} AND hyperlink_task_id=#{taskId} AND id IN
#{id}
ORDER BY id FOR UPDATE

mapper.update:
UPDATE hyperlink_task_round SET round_status=8, finished_at=#{now},
  version=version+1, updated_at=#{now}
WHERE hyperlink_task_id=#{taskId} AND round_status IN (1,2,3,4,5,7,10)

UPDATE hyperlink_task_round SET started_at=COALESCE(started_at,#{now}),
  next_dispatch_at=#{now}, version=version+1, updated_at=#{now}
WHERE id=#{id} AND round_status IN (3,10) AND started_at IS NULL
  AND scheduled_at<=#{now}

UPDATE hyperlink_task_round SET round_status=5, dispatch_completed_at=#{now},
  version=version+1, updated_at=#{now}
WHERE id=#{id} AND round_status IN (3,4)

UPDATE hyperlink_task_round SET round_status=3, next_dispatch_at=#{now},
  version=version+1, updated_at=#{now}
WHERE hyperlink_task_id=#{taskId} AND round_status=7
